insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('65941383-8920-456d-9564-8f938de86fed', 'fr', 'Quels comportements t’aident à ne pas être d’accord sans perdre le lien ?', '["Présenter ton avis comme une vérité absolue", "Lui poser des questions sur son raisonnement", "Garder un ton calme", "Laisser exister les deux points de vue"]'::jsonb, 'Le lien survit quand on explore la différence au lieu de la balayer.')
