insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('76af82d7-0b8b-4c02-ad43-4cff911e6e4f', 'fr', 'Quel état d’esprit permet le mieux de bien partir, de manière générale ?', '["Repérer des fils à prolonger", "Espérer tomber au bon moment", "Chercher à marquer les esprits", "Partir vite pour éviter la gêne"]'::jsonb, 'Rappeler un fil donne une raison naturelle de reprendre contact.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('79854e99-6c36-4456-94b9-a4a09f901b6e', 'fr', 'Pourquoi la reconnaissance crée-t-elle un sentiment de sécurité ?', '["On sent que ce qu’on vit est reconnu et compris", "Elle montre de l’intelligence émotionnelle et de l’empathie", "La reconnaissance fait qu’on se sent important et apprécié"]'::jsonb, 'Quand elle se sent comprise, elle s’ouvre plus naturellement.')
