insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('7f4038e9-35fa-4928-b87c-513fe0b81ce9', 'fr', 'Elle parle d’une journée stressante. Qu’est-ce que tu dois éviter ?', '["Dire : « Cet endroit me détend toujours après une longue journée. »", "Demander : « Qu’est-ce qui a rendu ta journée stressante ? »", "Remarquer : « Tu as l’air de bien gérer le stress. »"]'::jsonb, 'Associe-toi à des émotions positives ; ne la questionne pas sur son stress.')
