insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('8105c1a4-951f-4041-9374-fb7c65a70dca', 'fr', 'Quels fils t’offre « Je suis avocate » ?', '["Son rôle précis et ses responsabilités", "Le domaine du droit dans lequel elle exerce", "Son expérience et son parcours professionnel", "Toutes les réponses ci-dessus"]'::jsonb, 'Rebondir sur un fil, c’est approfondir son sujet ; pose des questions précises sur ce qu’elle a mentionné.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('8389bf63-7797-4fed-8bf2-0f7cb7b996c7', 'fr', 'La conversation coule bien et elle rit. Que pourrais-tu dire pour proposer la suite comme une évidence ?', '["« Ça te dirait peut-être d’aller boire un café un de ces jours ? »", "« Je ne sais pas, mais on pourrait peut-être se voir ? »", "« Tu veux qu’on échange nos numéros ? »", "« Allons boire un café. C’est quoi, ton numéro ? »"]'::jsonb, 'Énonce la suite avec assurance, comme un fait, au lieu de demander la permission.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('8424db00-09f4-4aa8-b16b-d90b7a683c0b', 'fr', 'Pourquoi les longs monologues réduisent-ils l’attirance ?', '["Ils sonnent récités", "Ils lui enlèvent l’occasion de s’investir", "Ils ralentissent la conversation", "Ils en révèlent trop"]'::jsonb, 'Quand elle ne peut pas participer, son investissement baisse. Laisse-lui de la place pour partager.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('8578c723-b332-450d-8dd1-4eaad1b6150b', 'fr', 'Pourquoi relier ton histoire à son univers à elle ?', '["Ça crée un vrai échange au lieu de deux histoires parallèles", "Ça montre que tu te sers de l’histoire pour la comprendre", "Ça évite que la conversation paraisse cloisonnée", "Toutes les réponses ci-dessus"]'::jsonb, 'Relier fait de l’histoire un outil de lien, pas seulement une performance.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('87339858-15ab-4a2b-89af-d6a42cafac7a', 'fr', 'À quoi servent les phrases de reconnaissance ?', '["Montrer que ses mots t’ont vraiment touché", "Faire de la place pour un échange plus sincère", "Montrer de l’assurance et de la sensibilité émotionnelle", "La garder ancrée dans le moment, avec le sentiment d’être comprise"]'::jsonb, 'Reconnaître ses mots montre que tu les as entendus, ce qui l’invite à se confier davantage.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('97b34e22-5615-4aa3-bf23-73f5718f67c6', 'fr', 'Quelles façons de faire transforment une histoire en lien plutôt qu’en impasse ?', '["Finir en soulignant à quel point le résultat était impressionnant", "Lui demander ce que la situation lui évoque", "Rattacher l’histoire à quelque chose qu’elle a déjà mentionné"]'::jsonb, 'Les histoires créent du lien quand elles invitent son univers dans la conversation.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('97e7b932-511e-48e1-bf8b-9b0e49bd18f9', 'fr', 'Elle parle, et tu te rends compte que tu prépares ta réponse. Que dois-tu faire ?', '["Finir vite de préparer, puis te reconcentrer sur ce qu’elle dit", "Arrêter de préparer et reporter tout de suite ton attention sur ses mots", "Lui demander de répéter la fin, puisque tu as décroché"]'::jsonb, 'Remarque que tu décroches, puis ramène immédiatement ton attention sur ses mots et son ton.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('998825a4-01bc-40bc-9219-b9e8a227feb8', 'fr', 'Tu sens une tension après avoir donné un avis différent. Quelle est la façon la plus propre de rebondir ?', '["Adoucir ton ton et lui demander ce qu’elle en a vécu", "En remettre une couche avec plus d’arguments", "T’excuser de ne pas être d’accord"]'::jsonb, 'Passe de prouver à comprendre ; invite plutôt son expérience.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('9a3ada69-efcb-4e14-96d0-7d4c087e2d2a', 'fr', 'Qu’apportent surtout les observations et les affirmations à une conversation ?', '["Elles équilibrent l’échange", "Elles révèlent ton propre point de vue", "Elles l’obligent à répondre"]'::jsonb, 'Elles rendent l’échange partagé et chaleureux.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('9b82f398-1878-449a-baf9-24e1e9ec6c0d', 'fr', 'Pourquoi partager une expérience digérée crée-t-il du lien ?', '["Ça montre de la lucidité sur toi et de l’évolution", "Ça révèle une vulnérabilité sans lui faire porter un poids émotionnel", "Ça invite à la proximité sans l’obliger à t’aider", "Toutes les réponses ci-dessus"]'::jsonb, 'Quand une expérience est digérée, elle invite au lien plutôt qu’à prendre soin de toi.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('9bb0ed54-392a-4aab-9aed-715508c1df96', 'fr', 'Tu n’es pas d’accord avec son avis sur un film. Elle a l’air passionnée. Que pourrais-tu faire ensuite ?', '["Expliquer pourquoi son avis ne tient pas", "Dire : « J’aime bien ton point de vue. Pourquoi tu l’adores autant ? »", "Faire semblant d’être d’accord pour que ça reste fluide", "Passer tout de suite à un autre sujet"]'::jsonb, 'Montre de la curiosité pour sa passion pour rester connectés malgré vos différences.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('9d4b7485-9598-45ab-9df1-95a6de8dbd91', 'fr', 'Elle dit : « J’ai fini tard tous les soirs cette semaine. » Que pourrais-tu dire ensuite ?', '["« Tu fais quoi comme travail ? »", "« Tu as clairement mérité une soirée de sortie. »", "« Tu travailles combien d’heures ? »", "« Tu es fatiguée ? »"]'::jsonb, 'Une affirmation apporte quelque chose et l’invite à partager sans pression.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('9f096c93-c6af-4940-a92a-503d7c7f4a16', 'fr', 'Elle dit qu’elle a du mal dans son nouveau travail. Tu partages ta propre expérience. Et ensuite ?', '["« J’ai vécu la même chose. Bref… »", "« Et toi, comment tu gères l’adaptation pour l’instant ? »", "« Tu fais quoi exactement ? »"]'::jsonb, 'Relie-toi à sa situation actuelle pour inviter son point de vue et renforcer la complicité.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('9f811f6d-ea33-440c-a2f7-4e4f2eab4134', 'fr', 'Elle dit qu’elle est stressée par le travail. Quelle réponse crée une association positive ?', '["« Ça a l’air dur. Le travail, c’est brutal. »", "« Tu devrais mieux gérer ton temps. »", "« Tout le monde est stressé en ce moment. »", "« Qu’est-ce que tu as le plus hâte de faire une fois que ce sera fini ? »"]'::jsonb, 'Ça fait passer doucement son état émotionnel du stress au soulagement et à l’impatience.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('a3852cf6-c43a-47f6-95c6-432c2afa408f', 'fr', 'Vous marchez ensemble, et la conversation ralentit. Qu’est-ce qui signale une relance propre ?', '["Une pause détendue avant de réorienter", "Changer de sujet à toute vitesse", "Lui demander si elle s’ennuie"]'::jsonb, 'Le calme transmet plus d’assurance que la vitesse.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('a567d0df-afca-4f4d-bed2-fa676a9cd119', 'fr', 'Tu remarques qu’elle hoche la tête sans apporter grand-chose pendant que tu parles. Meilleur ajustement ?', '["Finir ton propos avec force", "Accélérer pour tout dire", "Marquer une pause et l’inviter à donner son point de vue", "Changer brusquement de sujet"]'::jsonb, 'Lui laisser la parole rétablit l’équilibre et l’invite à se réimpliquer.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('a6a5fa05-f1d7-453b-b228-4c8e34485599', 'fr', 'Que se passe-t-il quand tu ne fais que poser des questions ?', '["Elle fait tout le travail en fournissant le contenu", "La conversation ressemble à un entretien, pas à un lien", "Elle s’épuise à répondre sans arrêt", "Toutes les réponses ci-dessus"]'::jsonb, 'Trop de questions créent une dynamique où tu prends sans donner et où elle porte la conversation.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('a734d277-baef-4344-8dd3-962cd62d6ac3', 'fr', 'Pourquoi est-il important de t’associer à des émotions positives ?', '["Les émotions créent des associations plus fortes avec toi", "Les sensations positives lui donnent envie de passer plus de temps avec toi", "Les émotions négatives renforcent toujours l’attirance"]'::jsonb, 'L’attirance se construit sur ce qu’elle ressent en ta présence, pas seulement sur le contenu.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('a89cc880-19f7-430e-b699-51926d19b98b', 'fr', 'Elle donne un avis avec lequel tu n’es pas d’accord. Quelle réponse préserve le mieux le lien ?', '["Expliquer pourquoi son avis ne tient pas", "Être d’accord pour éviter la tension", "Changer tout de suite de sujet", "Reconnaître son point de vue et lui demander comment elle en est arrivée là"]'::jsonb, 'La curiosité garde l’échange coopératif plutôt que compétitif.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('a9785ffd-0cfe-4181-b029-10a0c6cc6131', 'fr', '« Je travaille dans la tech, mais le week-end, je suis peintre. » Meilleure façon de rebondir ?', '["« La tech et l’art, c’est un mélange intéressant. Comment c’est arrivé ? »", "« Ah, cool, tu fais quoi dans la tech ? »", "« La peinture ! Génial. Tu peins quoi ? »"]'::jsonb, 'Ça réunit les deux fils, montre que tu as tout entendu et lui ouvre la porte pour raconter son histoire.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('aa6e8752-217b-4419-a60b-1e74d05c3e39', 'fr', 'Elle raconte une histoire drôle et rit. Que doit faire ton langage corporel ?', '["Rester complètement immobile et neutre", "Sourire et hocher la tête au moment de la chute", "Regarder ailleurs pour ne pas paraître trop empressé", "Croiser les bras et te pencher en arrière"]'::jsonb, 'T’accorder à son énergie avec ton visage montre une implication sincère.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('ab4ba3e7-8e8e-4347-a113-cdb95d15d251', 'fr', 'Quels comportements cassent souvent le rythme d’une conversation ?', '["De longues histoires sans pause", "Des réponses courtes sans relance", "Partager un peu, puis laisser de l’espace", "Lui laisser la parole après avoir fait passer ton idée"]'::jsonb, 'Monopoliser comme se retirer déséquilibre le rythme.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('add28003-e846-44f9-b448-3449baa804b7', 'fr', 'Elle conteste ton avis. Qu’est-ce qui montre une réaction saine de ta part ?', '["Rester détendu et impliqué", "Énumérer des exemples pour prouver ce que tu dis", "Hausser le ton pour égaler son intensité", "Te retirer du sujet"]'::jsonb, 'Rester détendu montre que le désaccord ne te menace pas.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('af3e39be-381e-451e-aa88-6cebba413dad', 'fr', 'Lesquelles de ces phrases sont des phrases de reconnaissance ?', '["« Ça a l’air pénible. »", "« Je comprends pourquoi ça compte pour toi. »", "« Pourquoi c’est arrivé ? »", "« Ça a dû être dur. »"]'::jsonb, 'De brèves reconnaissances montrent que ses mots ont du poids.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('b14823ef-b8ce-4062-8fcb-4cfcf41fc931', 'fr', 'Quand le désaccord devient-il un problème ?', '["Quand avoir raison compte plus que garder le lien", "Quand les avis sont trop différents pour trouver un terrain d’entente", "Quand il arrive trop tôt, avant que la confiance soit là"]'::jsonb, 'Le lien se rompt quand avoir raison devient plus important que comprendre.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('b284a2c4-70e8-4c60-91c5-92cbc5e68edf', 'fr', 'Elle s’illumine en parlant d’une passion. Tu dois partir. Qu’est-ce qui peut guider ta dernière phrase ?', '["Partir efficacement", "Éviter la pression", "Faire court", "Faire référence à ce qui l’enthousiasmait"]'::jsonb, 'Partir sur ce qui comptait pour elle préserve le ton émotionnel de l’échange.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('b5ac4b83-5b84-4914-8cdf-cbba23aa7ff4', 'fr', 'La conversation est légère et amusante, sur vos adresses de ramen préférées. Comment concrétiser ?', '["« On devrait sortir ensemble un de ces jours. Je peux t’inviter à dîner ? »", "« Je t’envoie l’adresse du resto de ramen dont je t’ai parlé. C’est quoi, ton numéro ? »", "« On se voit bientôt ? Tu es libre quand ? »"]'::jsonb, 'Une petite suite sans enjeu colle au ton et paraît naturelle.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('b7fd7470-ddb6-4107-9390-97cff5fc0696', 'fr', 'Pourquoi un au revoir passe-partout casse-t-il l’élan après une bonne conversation ?', '["Les messages qui suivent paraissent sortis de nulle part", "Il ne lui laisse rien de précis dont se souvenir ou pour reprendre contact", "Il montre que tu écoutais attentivement"]'::jsonb, 'Une sortie passe-partout ferme complètement l’échange au lieu de faire le pont vers la suite.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('bac16dba-494e-42a6-85ef-76041bd6b867', 'fr', 'Pourquoi écouter pour répondre empêche-t-il un vrai lien ?', '["Ton esprit se concentre sur ta prochaine phrase au lieu de ses mots", "Tu rates le sous-texte et les signaux émotionnels", "Tes réponses paraissent génériques et décalées", "Ça montre que tu es pleinement présent dans le moment"]'::jsonb, 'Préparer tes réponses tourne ton attention vers toi et montre que tu ne l’écoutes pas vraiment.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('bb4ac1da-dc29-41e3-a551-022813ad2ba6', 'fr', 'Elle dit qu’elle est libre ce week-end. Quelle suite proposée comme une évidence convient le mieux ?', '["« Tu voudrais aller dîner ? »", "« Tu crois qu’on devrait se voir ? »", "« On se voit, alors. C’est quoi, ton numéro ? »", "« Un dîner, peut-être, si ça t’intéresse ? »"]'::jsonb, 'Considère le projet comme acquis et passe à l’organisation avec assurance.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('bf592d93-816d-437d-bf97-761e412be0fa', 'fr', 'Pourquoi répondre au sous-texte crée-t-il du lien ?', '["Ça montre que tu écoutes au-delà des mots", "Ça garde la conversation en surface", "Elle se sent vraiment comprise", "Ça reconnaît l’émotion derrière ce qu’elle dit"]'::jsonb, 'Le sous-texte révèle le vrai message ; y répondre crée l’accord entre vous.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('c46c2263-5933-4984-8b1a-1cb44756f991', 'fr', 'Pourquoi les longues histoires racontées étape par étape perdent-elles souvent l’attention ?', '["Elles paraissent malhonnêtes", "Elles sont trop intimes", "Elles trahissent de l’insécurité", "Elles demandent trop d’effort pour suivre"]'::jsonb, 'Quand on doit faire un effort pour suivre, le lien émotionnel baisse.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('c6ab667b-89c1-40bf-81ce-fc391a31cf88', 'fr', 'Pourquoi une conversation doit-elle rester légère au début ?', '["La confiance a besoin de temps avant les sujets plus lourds", "Partager une expérience non digérée crée un déséquilibre", "Des détails digérés invitent naturellement à la proximité", "La profondeur vaut toujours mieux dès le départ"]'::jsonb, 'Des bases légères permettent au lien de grandir en toute sécurité.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('c7773b16-20a8-4e4f-b8d5-ce0164ce4e7a', 'fr', 'Pourquoi une grosse demande crée-t-elle souvent de l’hésitation, même après une bonne conversation ?', '["Elle fait monter l’enjeu d’un coup", "Elle paraît récitée", "Elle paraît en manque", "Elle réduit l’attirance"]'::jsonb, 'Quand l’enjeu monte trop vite, on recule par instinct.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('c8c65a67-7bdf-4ffa-95d7-4d6f1b019a36', 'fr', 'Trois questions d’affilée : elle répond, mais l’énergie est plate. Que dois-tu faire ensuite ?', '["Poser une question plus prenante pour regagner son intérêt", "Passer à un sujet qui la passionne davantage", "Faire une affirmation ou une observation pour équilibrer l’échange"]'::jsonb, 'Une observation lui donne quelque chose à quoi réagir sans l’obligation de répondre.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('c9c21217-6720-474d-becb-eea9a3d28503', 'fr', 'Elle dit : « J’ai étudié la psycho, mais je me suis retrouvée dans le design produit. » Quels fils s’offrent à toi ?', '["« La psycho, c’est passionnant. Ma sœur en fait aussi »", "« Tu as étudié la psycho où ? »", "« Sacré changement. Qu’est-ce qui t’a fait passer de la psycho au design ? »"]'::jsonb, 'Lui demander ce qui l’a fait passer de la psycho au design explore la transition, la partie la plus intéressante de ce qu’elle a dit.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('cb95d0ef-b417-4041-9b25-7d3df8389f7c', 'fr', 'Qu’est-ce qui rend les observations efficaces dans une conversation ?', '["Elles montrent que tu fais attention aux détails", "Elles lui donnent quelque chose à quoi réagir sans rien exiger", "Elles créent un moment partagé au lieu de soutirer des informations", "Elles montrent une grande assurance"]'::jsonb, 'Les observations montrent ton attention, invitent à réagir sans pression et encouragent à partager.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('cbd5d720-2cda-427f-b70b-062656b318b6', 'fr', 'Que veut dire « s’accorder » dans une conversation ?', '["Parler à peu près au même volume qu’elle", "S’accorder à la profondeur émotionnelle de ce qu’elle partage", "Refléter son ton et sa façon de communiquer", "Être d’accord avec les opinions qu’elle exprime"]'::jsonb, 'S’accorder crée de l’aisance en alignant la façon de s’exprimer, pas les opinions.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('cca7a715-1724-4e42-a043-6c5cfa837473', 'fr', 'Elle confie quelque chose d’intime sur sa reconversion. Que dois-tu faire ensuite ?', '["Donner tout de suite un conseil ou la rassurer", "Marquer une pause, soutenir son regard et hocher la tête", "Poser tout de suite une question de relance", "Changer de sujet pour garder l’élan"]'::jsonb, 'Le silence laisse de l’espace à la conversation et approfondit le moment.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('cfd11024-05eb-4caa-a51a-88939ceb81d5', 'fr', 'Que se passe-t-il en général quand quelqu’un sent que son sous-texte est compris ?', '["Ses réponses raccourcissent", "Il se détend et développe", "Il change de sujet", "Il devient plus méfiant"]'::jsonb, 'Se sentir compris invite à l’ouverture et à se confier davantage.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('d226b626-28f6-4109-8268-b01d9a460890', 'fr', 'Quel est le rôle principal d’une relance qui reconnaît ce qu’elle a dit ?', '["La conseiller sur sa situation", "Montrer que sa réponse compte avant de continuer", "Changer de sujet en douceur", "Poser tout de suite des questions plus profondes"]'::jsonb, 'La reconnaissance marque une pause pour saluer ce qu’elle a dit, ce qui fait de la place pour le lien.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('d38324bc-d000-4a3f-a909-0c700d82ce65', 'fr', 'L’énergie est forte, mais tu parles depuis un moment. Que dois-tu faire ?', '["Continuer pour garder l’élan", "Marquer une pause et lui demander ce qu’elle pense de ce que tu as dit", "T’excuser d’avoir trop parlé", "Mettre fin à l’échange"]'::jsonb, 'Laisse-lui la parole pour rétablir l’aller-retour et éviter le monologue.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('d45e9b83-7cd7-4c69-b73b-89ec09e1fe8d', 'fr', 'Elle rit et se penche vers toi. Tu veux son numéro. Qu’est-ce qui marche le mieux ?', '["« Mets ton numéro là, on continue ça. »", "« Ça te dérangerait de me donner ton numéro ? »", "« Tu veux qu’on reste en contact ? »", "« On pourrait peut-être s’écrire un de ces jours ? »"]'::jsonb, 'Lui tendre ton téléphone en considérant la suite comme acquise, avec décontraction, lui rend le oui facile, et elle peut toujours dire non.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('d8feb1b5-d12d-4bee-96bc-68092a37c841', 'fr', 'Pourquoi une baisse d’énergie n’est-elle pas la même chose qu’un manque d’intérêt ?', '["Elle arrive souvent quand un sujet est épuisé", "Elle peut venir d’un sujet sensible", "C’est un point de friction normal dans le fil de la conversation", "Toutes les réponses ci-dessus"]'::jsonb, 'Les baisses d’énergie sont des transitions normales, pas des signes de rejet.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('de05395b-2be8-4a0f-a1a9-f8ccc2dea698', 'fr', 'Qu’apportent les observations et les affirmations que les questions seules n’apportent pas ?', '["Elles réduisent la pression", "Elles montrent ton attention", "Elles équilibrent l’effort dans la conversation", "Elles l’obligent à répondre"]'::jsonb, 'Les observations et les affirmations invitent à répondre sans l’exiger.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('df1e06ae-6ab7-4483-aa1a-c651e45f6383', 'fr', 'Lesquels de ces signes non verbaux montrent une bonne écoute ?', '["Être bien tourné vers elle", "Un regard naturel", "Te pencher légèrement vers elle", "Une posture fermée et les bras croisés"]'::jsonb, 'Un langage corporel ouvert montre ton intérêt et fait qu’elle se sent appréciée.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('e32b283b-6ea1-4914-8d33-e58a17093c39', 'fr', 'Elle dit : « Il y a une super ambiance dans ce bar. » Quelle réponse est une observation ?', '["« Tu viens souvent ici ? »", "« Oui, la musique ici est toujours parfaite. »", "« Qu’est-ce qui te plaît ici ? »", "« C’est ton bar préféré ? »"]'::jsonb, 'Une affirmation partage ton point de vue et rend la réponse facile.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('e6a811b3-1df2-496e-a632-731de2c90037', 'fr', 'Elle partage quelque chose qui compte pour elle. Quelle réponse approfondit le lien émotionnel ?', '["Reconnaître pourquoi ça compte pour elle", "Proposer des solutions", "Raconter tout de suite une histoire semblable", "Changer de sujet pour garder une ambiance légère"]'::jsonb, 'Se sentir vue crée de la chaleur et un sentiment de sécurité émotionnelle.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('f1489d76-0230-4524-9918-2a7b8ca71d2d', 'fr', 'Qu’apporte à l’échange le fait d’écouter pour comprendre ?', '["Elle se sent vraiment écoutée", "Ça te permet de saisir le sous-texte et les détails", "Ça crée un lien plus naturel", "Ça accélère le rythme de la conversation"]'::jsonb, 'Une présence entière crée l’accord entre vous et transforme la discussion en vraie compréhension.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('f4b3b908-47e7-45ae-9eb6-f5261d6f7325', 'fr', 'Elle te parle de voyages. Tu racontes tout ton itinéraire. L’énergie retombe. Meilleure approche ?', '["Lui demander d’abord ses voyages à elle avant de parler des tiens", "Raconter tous les moments forts en sautant la logistique ennuyeuse", "Choisir un moment précis et marquant du voyage"]'::jsonb, 'Concentre-toi sur ce que tu veux qu’elle comprenne, pas sur tout ce qui s’est passé.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('f5c61ea0-9f18-4235-a9ab-6adb6c8b8aac', 'fr', 'Pourquoi répondre au sous-texte crée-t-il du lien ?', '["Ça montre que tu as de l’intelligence émotionnelle et du flair", "Elle se sent comprise parce que tu as entendu son vrai message", "Ça montre que tu fais plus attention que les autres", "Les réactions émotionnelles créent l’attirance plus vite que la logique"]'::jsonb, 'Le sous-texte porte le vrai message ; réponds-y pour qu’elle se sente vraiment comprise.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('faa961fa-7141-46c3-a897-d3e92bbb1ede', 'fr', 'Pourquoi le rire est-il un ancrage émotionnel si puissant ?', '["Il crée une émotion positive partagée sur le moment", "Il montre une domination sociale", "Il montre ton intelligence", "Il fait oublier la gêne"]'::jsonb, 'Rire ensemble crée tout de suite une association positive et de l’aisance.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('fc6a4d99-9dc3-4483-b053-8182553c1e5c', 'fr', 'Quel est le meilleur état d’esprit quand l’énergie baisse dans une conversation ?', '["Y voir quelque chose de normal et réorienter calmement", "Y voir un échec et en faire trop pour compenser", "L’ignorer et rester sur le même sujet", "Mettre fin tout de suite à l’échange"]'::jsonb, 'Rester stable préserve ton calme et rétablit naturellement le rythme.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('fc8e3792-e6b6-47b1-b102-f1ec0d9d980b', 'fr', 'Elle parle d’une reconversion. Tu es passé par là toi aussi. Meilleure réponse ?', '["« Je vis la même chose en ce moment, c’est horrible »", "Ignorer ce qu’elle a dit et changer de sujet", "« J’ai déjà changé de voie ; c’était difficile, mais ça en valait la peine »"]'::jsonb, 'Partage ce que tu as tiré d’une expérience digérée pour créer du lien sans trop dévoiler ta douleur.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('fe98319f-7a07-4376-a92b-a4c12040ed64', 'fr', 'Pourquoi reconnaître sa réponse crée-t-il un sentiment de sécurité ?', '["Ça montre que ce qu’elle vit compte", "Elle se sent comprise, et ça l’aide à s’ouvrir", "Ça fait passer vite à la question suivante"]'::jsonb, 'La reconnaissance montre que ses mots ont été entendus, ce qui favorise un échange sincère.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
commit;
